const {test}=require('node:test'),assert=require('node:assert/strict');
const C=require('./collection-flow-model'),M=require('./model'),P=require('./product-model');
const base=()=>({sequence:300,issues:[{id:'I',device:'other',version:'wrong',build:'wrong',status:'调查中',requests:[],evidence:[],updates:[]}],collectionRequests:[]});
const form=(targetId='native-a17')=>({targetId,issueId:'',begin:'2026-10-19T10:40',end:'2026-10-19T10:45',types:['应用日志'],expanded:true,title:'查登录',budget:'32',ttl:'30',notify:true});
test('独立采集不产生工单；发送身份来自目标，构建保持未知',()=>{const s=base(),r=C.create(s,form(),M,P);assert.equal(s.issues.length,1);assert.equal(s.collectionRequests.length,1);assert.equal(r.platform,'Native');assert.equal(r.build,null);assert.equal(r.product.target.latestBuild,'38108');});
test('工单版本只是预期线索，不成为日志实际身份',()=>{const s=base(),r=C.create(s,{...form(),issueId:'I'},M,P);assert.equal(r.build,null);assert.equal(r.product.expected.build,'wrong');assert.equal(r.device,'demo-A17');});
test('Web 目标自动使用 Web 能力，不沿用 Native 日粒度',()=>{const s=base(),r=C.create(s,form('web-active'),M,P);assert.equal(r.platform,'Web');assert.equal(r.product.profile,'precise');assert.equal(r.product.scope.expanded,false);});
test('未知或离线目标、未确认日范围、关闭工单均不能发送',()=>{for(const patch of [{targetId:'missing'},{targetId:'web-offline'},{expanded:false}])assert.throws(()=>C.create(base(),{...form(),...patch},M,P));const s=base();s.issues[0].status='已解决';assert.throws(()=>C.create(s,{...form(),issueId:'I'},M,P),/已解决/);});
test('独立请求关联保留 ID、原范围、构建及历史，重复关联不重复',()=>{const s=base(),r=C.create(s,form(),M,P);r.product.observed={build:'observed'};C.associate(s,r.id,'I');C.associate(s,r.id,'I');assert.equal(s.collectionRequests.length,0);assert.equal(s.issues[0].requests.length,1);assert.equal(r.product.observed.build,'observed');assert.equal(r.product.stableKey,'collection/'+r.id);});
test('重复请求给出已有对象，不隐式覆盖计划',()=>{const s=base();C.create(s,form(),M,P);assert.throws(()=>C.create(s,form(),M,P),/已有相同目标/);assert.equal(s.collectionRequests.length,1);});
test('可读文件数与观察事件不代表连续覆盖',()=>{const r={task:'T',files:[{status:'可查'}],product:{observed:{records:[{time:'2026-10-19T10:42:01+08:00'},{time:'2026-10-19T10:42:09+08:00'}]}}};const c=C.coverage(r);assert.equal(c.continuous,false);assert.equal(c.count,2);assert.match(c.label,/尚未确认/);});
test('未知返回元数据不会使用最近已知版本补全',()=>{const s=base(),r=C.create(s,form(),M,P);C.observe(r,{records:[],build:null,version:null});assert.equal(r.build,null);assert.equal(r.version,null);assert.equal(r.product.target.latestBuild,'38108');});
test('回捞推送保存应用路由与指令，通道接受前没有客户端文件',()=>{const s=base(),r=C.create(s,form(),M,P);assert.equal(r.product.push.status,'待提交');assert.equal(r.product.push.command.begin,'2026-10-19T00:00');assert.equal(r.product.push.binding.recipient,'push-install-a17');assert.equal(C.dispatch(r,M),true);assert.equal(r.status,'通道已接受');assert.equal(r.product.push.status,'通道已接受');assert.equal(r.files.length,0);assert.equal(r.task,null);assert.ok(r.product.push.receiptId);assert.ok(r.product.push.expiresAt);assert.equal(r.events.some(e=>e.text.includes('SDK 已确认')),false);});
test('同一请求重复提交不会再次发送；通道拒绝不会产生设备回执或文件',()=>{for(const scenario of ['success','pushfail']){const r=C.create(base(),form(),M,P);r.scenario=scenario;C.dispatch(r,M);const n=r.events.length;assert.equal(C.dispatch(r,M),false);assert.equal(r.events.length,n);assert.equal(r.files.length,0);if(scenario==='pushfail'){assert.equal(r.product.push.status,'通道拒绝');assert.equal(r.product.push.receiptId,null);assert.equal(r.step,0);}}});
test('Web 会话需消息通道绑定，历史离线会话不能作为推送目标',()=>{const t=C.target('web-active');assert.match(C.requirePush(t).channel,/业务消息通道/);assert.throws(()=>C.requirePush(C.target('web-offline')),/推送绑定/);assert.throws(()=>C.requirePush({id:'unknown'}),/推送绑定/);});
